contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0));
        // acquire tokens once via getTokens (2500e18 default value)
        c.getTokens();
        uint256 myBefore = c.balanceOf(address(this));
        uint256 recBefore = c.balanceOf(recipient);
        require(amount <= myBefore);
        bool ok = c.transfer(recipient, amount);
        uint256 myAfter = c.balanceOf(address(this));
        uint256 recAfter = c.balanceOf(recipient);
        // a transfer exceeding the balance must revert
        bool reverted;
        try c.transfer(recipient, myAfter + 1) { reverted = false; }
        catch { reverted = true; }
        assert(ok && recAfter == recBefore + amount && myAfter + amount == myBefore && reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
