contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public {
        uint256 ownerBalBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        uint256 distributedBefore = c.totalDistributed();
        require(burnAmount > 0);
        require(burnAmount <= ownerBalBefore);
        c.burn(burnAmount);
        uint256 ownerBalAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();
        uint256 distributedAfter = c.totalDistributed();
        assert(
            ownerBalAfter == ownerBalBefore - burnAmount &&
            supplyAfter == supplyBefore - burnAmount &&
            distributedAfter == distributedBefore - burnAmount
        );
    }
    receive() external payable {}
}

