contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 amount) public {
        require(recipient != address(this));
        // fund the test contract (as msg.sender of c) via a distribution
        c.getTokens();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(recipient);
        bool reverted;
        if (amount > beforeSender) {
            try c.transfer(recipient, amount) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            c.transfer(recipient, amount);
            assert(c.balanceOf(address(this)) == beforeSender - amount && c.balanceOf(recipient) == beforeRecipient + amount);
        }
    }
    receive() external payable {}
}

